+/** Picks the best supported language from an Accept-Language header, or `fallback`. */
+export function pickLanguage(header, fallback = LANGUAGES[0]) {
+  const defaultLang = LANGUAGES.includes(fallback) ? fallback : LANGUAGES[0];
+  if (typeof header !== "string" || !header.trim()) return defaultLang;
+  const prefs = [];
+  header.split(",").forEach((part, index) => {
+    const [rawTag, ...params] = part.split(";").map((s) => s.trim());
+    if (!rawTag) return;
+    let q = 1;
+    for (const p of params) {
+      const m = /^q\s*=\s*(.+)$/i.exec(p);
+      if (!m) continue;
+      const parsed = m[1] === "" ? NaN : Number(m[1]);
+      if (!Number.isFinite(parsed) || parsed < 0 || parsed > 1) return;
+      q = parsed;
+    }
+    if (q === 0) return;
+    const primary = rawTag.split("-")[0].toLowerCase();
+    if (LANGUAGES.includes(primary)) prefs.push({ lang: primary, q, index });
+  });
+  prefs.sort((a, b) => b.q - a.q || a.index - b.index);
+  return prefs[0]?.lang ?? defaultLang;
+}
